    } },
  "bools" = { {
      "name" = "wmgMagicIntro",
      "value" = true,
      "comment" = "many sections of this book describe facets of the outdoor environment without considering that characters in the wilderness may have access to spells or magic items; the magic commentary gathered here is a starting point, not exhaustive, and some of it may seem obvious",
    }, {
      "name" = "wmgGeneralPoints",
      "value" = true,
      "comment" = "magic that specifically affects animals or plants is obvious and excluded unless noteworthy; fire magic enters only when the observation is noteworthy; nourishment-creating magic is excluded; items with no general outdoor application are excluded; practically any magic may have a specific application in a particular circumstance",
    }, {
      "name" = "wmgArrangement",
      "value" = true,
      "comment" = "the spell section (including cantrips) is alphabetical without regard to class; the magic item section is alphabetical, and items that duplicate listed spell effects are not repeated",
    }, {
      "name" = "wmgAffectFiresCampfire",
      "value" = true,
      "comment" = "an easy way to blaze a campfire or cookfire quickly without fire-building proficiency: the magic expires soon but by then the larger fuel is ignited and the fire burns on its own",
    }, {
      "name" = "wmgAirWalkAerialUse",
      "value" = true,
      "comment" = "useful for ascending or descending a steep incline or moving directly up or down near a cliff face; the air walker must reach a safe perch before the spell duration expires",
    }, {
      "name" = "wmgAiryWaterMoveRate",
      "value" = true,
      "comment" = "in the area of effect the movement rate equals the swimming rate, and other characters in the sphere or hemisphere cannot move faster than the spell-caster if they intend to remain within the affected area",
    }, {
      "name" = "wmgAlarmOutOfSight",
      "value" = true,
      "comment" = "the alarm guards an area that is not in the sentry line of sight, giving an added assist for a short time",
