      "name" = "wmgAlarmNotCampsite",
      "value" = true,
      "comment" = "unless the caster is of very high level it is not prudent to cast it on the campsite itself since it cannot cover enough area; a better tactic is a spot a short distance away, perhaps on a path toward or parallel to the campsite",
