      "name" = "wmgAnimalSummonLore",
      "value" = true,
      "comment" = "if the caster party contains a character with animal lore proficiency the Dungeon Master may let the caster know in advance at least one animal type available within range; the caster will certainly receive animals of that sort if that is what he desires",
    }, {
      "name" = "wmgAnimateObjectRocks",
      "value" = true,
      "comment" = "animating the rock at the bottom of a pile near a plateau edge and sending it over makes the others follow - no more orc archers",
