      "name" = "wmgAnimateRockIdea",
      "value" = true,
      "comment" = "animate rock: see animate object above for the same idea",
    }, {
      "name" = "wmgAuguryEdible",
      "value" = true,
      "comment" = "handy for determining if gathered greenery is edible in the absence of plant lore proficiency or as a safeguard against an incorrect estimation; the augury itself does not always produce accurate results",
