      "name" = "wmgBeeClimbingCheck",
      "value" = true,
      "comment" = "a character victimized by the bee cantrip in a precarious position on a moderate or severe slope or a cliff face must make a Climbing Check to avoid falling; a creature stung in a similar situation must also check to keep from falling",
