      "value" = true,
      "comment" = "the spell expires prematurely if the caster performs any strenuous physical or mental activity, is struck by a physical or magical attack, or loses consciousness",
    }, {
      "name" = "wmgConeHeatstrokeUse",
      "value" = true,
      "comment" = "at the Dungeon Master discretion cone of cold could be used in a non-damaging manifestation to let a character recover from heatstroke: kept cooled for an hour without suffering damage from the spell and thereby saved from further harm",
    }, {
