      "value" = true,
      "comment" = "control temperature is useful for protecting and aiding the recovery of someone suffering hypothermia, frostbite, heatstroke or another temperature-related malady",
    }, {
      "name" = "wmgCtrlTempGradual",
      "value" = true,
      "comment" = "extreme heat is not necessarily good for a cold victim - a frostbite victim might be harmed as much as helped by a sudden 100-degree rise, so gradual warming is more conducive to full recovery; a heatstroke victim benefits most from prompt exposure to freezing or near-freezing conditions to bring body temperature down rapidly",
    }, {
      "name" = "wmgCtrlTempDM",
      "value" = true,
      "comment" = "at the Dungeon Master discretion the caster may manipulate the temperature during the duration or may be forced to pick a target temperature and stick with it as long as the spell persists",
    }, {
      "name" = "wmgCtrlWeatherExtreme",
      "value" = true,
      "comment" = "sweltering heat cannot be made hotter and arctic cold cannot be made colder; at an extreme the temperature can only be moved in one direction, true even of the druidic version",
