      "name" = "wmgCtrlWindsNoLargeScale",
      "value" = true,
      "comment" = "control winds cannot change large-scale weather conditions such as moving storm clouds rapidly, because the area of effect is not nearly large enough to affect the upper atmosphere where those clouds are located",
    }, {
